public class InnerListenerRuleTransformFactory(Action<Humidifier.ElasticLoadBalancingV2.ListenerRuleTypes.Transform> factoryAction = null) : SubResourceFactory<Humidifier.ElasticLoadBalancingV2.ListenerRuleTypes.Transform>
{

    internal InnerListenerRuleRewriteConfigObjectFactory UrlRewriteConfigFactory { get; set; }

    internal InnerListenerRuleRewriteConfigObjectFactory HostHeaderRewriteConfigFactory { get; set; }

    protected override Humidifier.ElasticLoadBalancingV2.ListenerRuleTypes.Transform Create()
    {
        var transformResult = CreateTransform();
        factoryAction?.Invoke(transformResult);

        return transformResult;
    }

    private Humidifier.ElasticLoadBalancingV2.ListenerRuleTypes.Transform CreateTransform()
    {
        var transformResult = new Humidifier.ElasticLoadBalancingV2.ListenerRuleTypes.Transform();

        return transformResult;
    }
    public override void CreateChildren(Humidifier.ElasticLoadBalancingV2.ListenerRuleTypes.Transform result)
    {
        base.CreateChildren(result);

        result.UrlRewriteConfig ??= UrlRewriteConfigFactory?.Build();
        result.HostHeaderRewriteConfig ??= HostHeaderRewriteConfigFactory?.Build();
    }

} // End Of Class

